SELECT b.*, u.username as creator_name, CASE WHEN p.id IS NOT NULL OR b.creator_id = #{userId} THEN 1 ELSE 0 END as purchased FROM exercise_book b LEFT JOIN sys_user u ON b.creator_id = u.id LEFT JOIN book_purchase p ON b.id = p.book_id AND p.user_id = #{userId}
b.status = 1 AND (b.is_public = 1 OR b.creator_id IS NULL)
AND b.book_name LIKE CONCAT('%', #{bookName}, '%')
ORDER BY b.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM exercise_book b LEFT JOIN book_purchase p ON b.id = p.book_id AND p.user_id = #{userId}
b.status = 1 AND (b.is_public = 1 OR b.creator_id IS NULL)
AND b.book_name LIKE CONCAT('%', #{bookName}, '%')

SELECT b.*, u.username as creator_name,
       CASE WHEN p.id IS NOT NULL OR b.creator_id = #{userId} THEN 1 ELSE 0 END as purchased
FROM exercise_book b
LEFT JOIN sys_user u ON b.creator_id = u.id
LEFT JOIN book_purchase p ON b.id = p.book_id AND p.user_id = #{userId}
WHERE b.id = #{id}

